import { db } from "../lib/db";
import { SANDBOX } from "../lib/sandbox";
import { pve, node as defaultNode, pveFor, getGuestDiskUsage } from "../lib/proxmox";
import { effectiveDiskGB } from "../lib/extra-disk";
import {
  BW_PERIOD_MS,
  creditFromCounters,
  integrateRrdBytes,
  readBwMeterHealth,
  recordBwSweep,
  type BwSample,
} from "../lib/bandwidth";
import {
  nodeStorageUsage,
  nodeRamUsage,
  backupSummary,
  stuckJobs,
  workerHealth,
  sampleHealth,
  fmtAge,
  DISK_WARN_RATIO,
  RAM_WARN_RATIO,
  BACKUP_STALE_MS,
  QUEUE_BACKLOG_ALERT,
  STUCK_JOB_MS,
} from "../lib/monitoring";
import {
  nodeThresholds,
  proxmoxNodeUtil,
  hostingNodeUtil,
  severityFor,
  resolveFloor,
  NODE_CAP_COOLDOWN_HOURS,
  type NodeUtil,
  type DimUtil,
  type CapSeverity,
} from "../lib/node-capacity";
import { sendMail, layout, button } from "../lib/mailer";
import { reportsEmail } from "../lib/settings";
import { appUrl } from "../lib/email-render";

/**
 * Monitoring sweep — run periodically from the worker loop. Read-only checks
 * that raise dashboard notifications for all ADMINs when a threshold trips.
 *
 * Notifications are de-duplicated by title within a rolling window so a
 * persistent condition (e.g. a node stuck at 90% disk) alerts once every few
 * hours rather than every sweep.
 */

const DEDUPE_HOURS = Number(process.env.NXEON_ALERT_DEDUPE_HOURS ?? 3);

/**
 * Fan a single alert out to every ADMIN, unless an identically-titled alert
 * already went out within the dedupe window.
 */
export async function notifyAdmins(
  title: string,
  body: string,
  href = "/admin/monitoring"
): Promise<void> {
  const since = new Date(Date.now() - DEDUPE_HOURS * 60 * 60_000);
  const recent = await db.notification.findFirst({
    where: { title, createdAt: { gt: since } },
    select: { id: true },
  });
  if (recent) return;

  const admins = await db.user.findMany({ where: { role: "ADMIN" }, select: { id: true } });
  if (admins.length === 0) return;

  await db.notification.createMany({
    data: admins.map((a) => ({ userId: a.id, title, body, href })),
  });
}

// ---------------------------------------------------------------------------
// Node capacity warnings
//
// Compute per-node utilization (lib/node-capacity.ts) and reconcile it against
// the OPEN NodeAlert rows so the operator is warned BEFORE a node fills up and
// provisioning starts failing. Debounced by design: an alert fires on STATE
// CHANGE (a dimension newly crossing WARN/CRITICAL, or a WARN⇄CRITICAL
// escalation) and at most once per cooldown while a condition persists — never
// every sweep. It auto-RESOLVES (with hysteresis) when the node drops back under
// the warn line, or when the node itself is deleted.
// ---------------------------------------------------------------------------

const NODE_ALERT_HREF = "/admin/nodes";

/** Ops-facing email + in-app fan-out for a single node-capacity transition. */
async function notifyNodeCapacity(subject: string, bodyText: string): Promise<void> {
  // In-app for every ADMIN (notifyAdmins dedupes by title as a backstop; the
  // caller already gates on state-change/cooldown so this rarely bites).
  await notifyAdmins(subject, bodyText, NODE_ALERT_HREF);
  // Email ops. No `kind`/`userId` → always sends (fail-open), which is right for
  // an operational capacity alert. Best-effort: sendMail never throws.
  // Routes to the dedicated reports mailbox (reportsEmail) so these automated
  // capacity alerts don't clutter the human support inbox.
  try {
    const to = await reportsEmail();
    const html = layout(
      subject,
      `<p style="margin:0 0 16px;color:#cbd5e1;">${bodyText.replace(/\n/g, "<br/>")}</p>` +
        button(`${appUrl()}${NODE_ALERT_HREF}`, "Open node capacity"),
    );
    await sendMail({ to, subject: `[Nxeon ops] ${subject}`, html, text: bodyText });
  } catch (e) {
    console.error("[node-capacity] ops email failed", e);
  }
}

function dimBody(nu: NodeUtil, d: DimUtil, sev: CapSeverity, warnPct: number, critPct: number): string {
  const kind = nu.kind === "PROXMOX" ? "Compute node" : "Hosting node";
  return (
    `${kind} "${nu.name}" — ${d.dimension} at ${Math.round(d.pct)}% ` +
    `(${sev}; warn ${warnPct}% / critical ${critPct}%).\n${d.detail}.\n` +
    (sev === "CRITICAL"
      ? "This node is at or past the critical line — add capacity now; new provisioning here may fail or degrade it."
      : "This node is filling up — plan to add a node before it becomes critical.")
  );
}

/**
 * One reconciliation pass over every node's utilization vs the OPEN NodeAlert
 * rows. Safe to call every monitor cadence.
 */
export async function nodeCapacitySweep(): Promise<void> {
  if (SANDBOX) return; // no real nodes to size in the sandbox

  const t = await nodeThresholds();

  let utils: NodeUtil[];
  try {
    const [proxmox, hosting] = await Promise.all([proxmoxNodeUtil(t), hostingNodeUtil(t)]);
    utils = [...proxmox, ...hosting];
  } catch (e) {
    console.error("[node-capacity] utilization compute error", e);
    return;
  }

  let open: Array<{
    id: string;
    nodeKind: string;
    nodeId: string;
    dimension: string;
    severity: string;
    lastNotifiedAt: Date | null;
  }>;
  try {
    open = await db.nodeAlert.findMany({
      where: { status: "OPEN" },
      select: { id: true, nodeKind: true, nodeId: true, dimension: true, severity: true, lastNotifiedAt: true },
    });
  } catch (e) {
    console.error("[node-capacity] could not read open alerts", e);
    return;
  }
  const openByKey = new Map(open.map((a) => [`${a.nodeKind}:${a.nodeId}:${a.dimension}`, a]));

  const now = new Date();
  const cooldownMs = NODE_CAP_COOLDOWN_HOURS * 60 * 60_000;
  const floor = resolveFloor(t);
  // Every (kind,id,dimension) we actually evaluated this sweep — so a dimension
  // that was merely ABSENT (e.g. Proxmox unreachable, so no CPU/DISK reading) is
  // never mistaken for "recovered".
  const evaluated = new Set<string>();
  const nodeIds = new Set(utils.map((u) => `${u.kind}:${u.id}`));

  for (const nu of utils) {
    for (const d of nu.dims) {
      const key = `${nu.kind}:${nu.id}:${d.dimension}`;
      evaluated.add(key);
      const sev = severityFor(d.pct, t);
      const existing = openByKey.get(key);
      const roundedPct = Math.round(d.pct);
      const metric = {
        allocPct: d.allocPct === null ? null : Math.round(d.allocPct),
        realPct: d.realPct === null ? null : Math.round(d.realPct),
        warnPct: t.warnPct,
        critPct: t.critPct,
      };

      if (sev === "OK") {
        // Auto-resolve, but only once we've dropped a hysteresis margin below WARN.
        if (existing && d.pct < floor) {
          try {
            await db.nodeAlert.update({
              where: { id: existing.id },
              data: { status: "RESOLVED", pct: roundedPct, detail: d.detail, resolvedAt: now },
            });
            await notifyNodeCapacity(
              `Node capacity cleared: ${nu.name} — ${d.dimension}`,
              `${nu.kind === "PROXMOX" ? "Compute node" : "Hosting node"} "${nu.name}" ${d.dimension} ` +
                `is back to ${roundedPct}% (below the ${t.warnPct}% warn line). Capacity warning resolved.`,
            );
          } catch (e) {
            console.error(`[node-capacity] resolve failed for ${key}`, e);
          }
        }

