};

export type NodeUtil = {
  kind: NodeKind;
  id: string;
  name: string;
  enabled: boolean;
  /** For Proxmox: node status endpoint reachable. Hosting is DB-only → always true. */
  reachable: boolean;
  dims: DimUtil[];
  /** Worst dimension percent across `dims` (0 when there are none). */
  worstPct: number;
  severity: CapSeverity;
};

function pct(part: number, whole: number): number | null {
  if (!(whole > 0)) return null;
  return (part / whole) * 100;
}

/** Combine allocation + real into the thresholded value (worse of the two). */
function worse(allocPct: number | null, realPct: number | null): number {
  return Math.max(allocPct ?? 0, realPct ?? 0);
}

function rollup(dims: DimUtil[], t: NodeThresholds): { worstPct: number; severity: CapSeverity } {
  const worstPct = dims.reduce((m, d) => Math.max(m, d.pct), 0);
  return { worstPct, severity: severityFor(worstPct, t) };
}

