/** Every vmid that still owns an archive in the `backup` storage, via a node-scoped client. */
export async function archivedVmids(client: TaskClient): Promise<Set<number>> {
  const content: StorageBackupEntry[] = await client.get(
    `/nodes/${client.node}/storage/backup/content`,
    { content: "backup" }
  );
  const out = new Set<number>();
  for (const b of content ?? []) {
    if (typeof b?.vmid === "number" && Number.isInteger(b.vmid)) out.add(b.vmid);
  }
  return out;
}

