export type BwMeterHealth = {
  /** When metering first ran. Null = never — show no usage figure at all. */
  startedAt: Date | null;
  /** Start of the most recent sweep. */
  lastAt: Date | null;
  /** Last unrecoverable metering outage (traffic in that gap is uncounted). */
  gapAt: Date | null;
  /** Last RRD back-fill — rates spanning it are inflated, see the key's doc. */
  backfillAt: Date | null;
  /** A sample landed within BW_STALE_MS. */
  live: boolean;
  /** Age of `lastAt`, or null if never metered. */
  ageMs: number | null;
};

function parseDate(raw: string): Date | null {
  if (!raw) return null;
  const d = new Date(raw);
  return Number.isNaN(d.getTime()) ? null : d;
}

/** Read the metering markers. One query per key; all four are tiny strings. */
export async function readBwMeterHealth(now = Date.now()): Promise<BwMeterHealth> {
  const [started, last, gap, backfill] = await Promise.all([
    getSetting(BW_STARTED_AT_KEY, ""),
    getSetting(BW_LAST_AT_KEY, ""),
    getSetting(BW_GAP_AT_KEY, ""),
    getSetting(BW_BACKFILL_AT_KEY, ""),
  ]);
  const startedAt = parseDate(started);
  const lastAt = parseDate(last);
  const ageMs = lastAt ? Math.max(0, now - lastAt.getTime()) : null;
  return {
    startedAt,
    lastAt,
    gapAt: parseDate(gap),
    backfillAt: parseDate(backfill),
    live: ageMs !== null && ageMs <= BW_STALE_MS,
    ageMs,
  };
}

