/**
 * Utilization for every HostingNode. Purely DB-derived (the accounts and their
 * quotas live in our own tables), so it is always reachable:
 *   - ACCOUNTS: live account count vs `HostingNode.maxAccounts` — the hard
 *     scheduler cap; the next account is refused once it's full.
 *   - DISK: worse of committed quota (Σ diskQuotaMB) and measured usage
 *     (Σ diskUsedMB, filled by hostingUsageSweep) vs `diskTotalGB`.
 */
export async function hostingNodeUtil(t: NodeThresholds): Promise<NodeUtil[]> {
  const nodes = await db.hostingNode.findMany({ orderBy: { name: "asc" } });

  return Promise.all(
    nodes.map(async (n) => {
      const [count, agg] = await Promise.all([
        db.hostingAccount.count({
          where: { hostingNodeId: n.id, status: { in: [...HOSTING_LIVE_STATUSES] } },
        }),
        db.hostingAccount.aggregate({
          where: { hostingNodeId: n.id, status: { in: [...HOSTING_LIVE_STATUSES] } },
          _sum: { diskQuotaMB: true, diskUsedMB: true },
        }),
      ]);

      const totalDiskMB = n.diskTotalGB * 1024;
      const quotaMB = agg._sum.diskQuotaMB ?? 0;
      const usedMB = agg._sum.diskUsedMB ?? 0;

      const dims: DimUtil[] = [];

      // ACCOUNTS
      {
        const allocPct = pct(count, n.maxAccounts);
        const p = allocPct ?? 0;
        dims.push({
          dimension: "ACCOUNTS",
          pct: p,
          allocPct,
          realPct: null,
          detail: `${count} / ${n.maxAccounts} accounts`,
        });
      }

      // DISK
      {
        const allocPct = pct(quotaMB, totalDiskMB);
        const realPct = pct(usedMB, totalDiskMB);
        const p = worse(allocPct, realPct);
        const parts = [`${(quotaMB / 1024).toFixed(0)} GB quota of ${n.diskTotalGB} GB`];
        if (realPct !== null) parts.push(`${(usedMB / 1024).toFixed(0)} GB used`);
        dims.push({ dimension: "DISK", pct: p, allocPct, realPct, detail: parts.join(" · ") });
      }

      return {
        kind: "HOSTING" as const,
        id: n.id,
        name: n.name,
        enabled: n.enabled,
        reachable: true,
        dims,
        ...rollup(dims, t),
      };
    }),
  );
}

/** Every node (both kinds) with its utilization, plus the resolved thresholds. */
export async function allNodeUtil(): Promise<{ thresholds: NodeThresholds; nodes: NodeUtil[] }> {
  const thresholds = await nodeThresholds();
  const [proxmox, hosting] = await Promise.all([
    proxmoxNodeUtil(thresholds),
    hostingNodeUtil(thresholds),
  ]);
  return { thresholds, nodes: [...proxmox, ...hosting] };
}

