/**
 * Data layer for the platform-wide Live Ops monitor (/admin/monitor).
 *
 * This is a v1 built entirely on data the platform ALREADY collects — it adds
 * no new sampling, no new schema. Three real sources are fused into one feed:
 *
 *   1. Node utilization (`lib/node-capacity.ts` allNodeUtil) — CPU/RAM/DISK for
 *      Proxmox compute nodes, ACCOUNTS/DISK for hosting nodes. CPU/RAM are
 *      queried LIVE from Proxmox on every call (no caching) — this is the one
 *      genuinely real-time number in the feed. DISK is the pool's live status
 *      too. This is the exact function that already powers the node-capacity
 *      warning banner and the Nodes admin page.
 *   2. Recent actions — the `Job` table (every VPS + game-server provisioning/
 *      power/backup/etc. action) fused with `HostingTask` (the equivalent queue
 *      for shared-hosting accounts, which do NOT create Job rows — see
 *      worker/hosting.ts). Together these cover every server kind the platform
 *      runs. Zero new instrumentation: both tables are written by the existing
 *      action/worker code on every real operation.
 *   3. Per-server resource state — `Server.bwInBytes/bwOutBytes` (metered by
 *      lib/bandwidth.ts on the worker's 10-minute sweep), the latest
 *      `ServerDiskSample` row (same sweep, guest-agent disk usage), and for
 *      shared hosting `HostingAccount.diskUsedMB`/`serveHttpOk`/`serveHttpsOk`
 *      (hostingUsageSweep / hostingHealthSweep). These are real but NOT
 *      per-request-live — they refresh on the worker's cadence (~10 min) and
 *      each row's own timestamp is returned so the UI can say exactly how
 *      stale it is instead of implying it's instantaneous.
 *
 * WHAT THIS DELIBERATELY DOES NOT DO: there is no live per-VM CPU/RAM series
 * (Proxmox reports that per-VM, but nothing persists it, and polling every VM's
 * `/qemu/{vmid}/status/current` on every fleet-wide poll would multiply load on
 * Proxmox by the server count for every admin with this tab open) and there is
 * no live connection/session count anywhere on the platform (RCON can fetch a
 * Minecraft server's online-player count, but only one server at a time, on
 * demand — there is no fleet-wide sweep that samples it). Both are real v2
 * candidates, not faked here. See the doc comment on `MonitorFeed.gaps`.
 */
import { db } from "./db";
import { allNodeUtil, type NodeUtil } from "./node-capacity";
import { readBwMeterHealth, bwUsageView, type BwUsageView } from "./bandwidth";

const ACTION_FEED_LIMIT = 60;
const SERVER_ROWS_LIMIT = 300;
const HOSTING_ROWS_LIMIT = 300;

export type ActionLogLine = {
  id: string;
  ts: string; // ISO
  source: "JOB" | "HOSTING_TASK";
  kind: "VPS" | "GAME" | "HOSTING";
  target: string; // hostname / primaryDomain / "—"
  action: string; // job type / task kind, lowercased
  status: string;
  attempts: number | null;
  error: string | null;
};

export type ServerRow = {
  id: string;
  hostname: string;
  label: string | null;
  kind: "VPS" | "GAME";
  status: string;
  bw: BwUsageView;
  disk: { usedBytes: number; totalBytes: number; ts: string } | null;
  portForwards: number;
  firewallRules: number;
};

export type HostingRow = {
  id: string;
  primaryDomain: string;
  status: string;
  diskUsedMB: number | null;
  diskQuotaMB: number;
  usageAt: string | null;
  serveHttpOk: boolean | null;
  serveHttpsOk: boolean | null;
};

export type MonitorFeed = {
  generatedAt: string;
  nodes: NodeUtil[];
  actions: ActionLogLine[];
  servers: ServerRow[];
  hosting: HostingRow[];
  totals: {
    serversByStatus: Record<string, number>;
    hostingByStatus: Record<string, number>;
    gameServers: number;
    vpsServers: number;
  };
  bwMeter: { live: boolean; startedAt: string | null; ageMs: number | null };
  gaps: string[];
};

/** A server is a "game server" iff it carries a GamePlan — same test the fleet UI uses elsewhere. */
function serverKind(s: { gamePlanId: string | null }): "VPS" | "GAME" {
  return s.gamePlanId ? "GAME" : "VPS";
}

export async function getMonitorFeed(): Promise<MonitorFeed> {
  const now = new Date();

  const [nodeUtilResult, jobs, hostingTasks, servers, hostingAccounts, bwHealth] = await Promise.all([
    allNodeUtil().catch((e) => {
      console.error("[monitor-feed] allNodeUtil failed", e);
      return { thresholds: { warnPct: 80, critPct: 90 }, nodes: [] as NodeUtil[] };
    }),
    db.job.findMany({
      orderBy: { createdAt: "desc" },
      take: ACTION_FEED_LIMIT,
      select: {
        id: true,
        type: true,
        status: true,
        attempts: true,
        error: true,
        createdAt: true,
        server: { select: { hostname: true, label: true, gamePlanId: true } },
      },
    }),
    db.hostingTask.findMany({
      orderBy: { createdAt: "desc" },
      take: ACTION_FEED_LIMIT,
      select: {
        id: true,
        kind: true,
        status: true,
        error: true,
        createdAt: true,
        account: { select: { primaryDomain: true } },
      },
    }),
    db.server.findMany({
      where: { status: { not: "DELETING" } },
      take: SERVER_ROWS_LIMIT,
      orderBy: { updatedAt: "desc" },
      select: {
        id: true,
        hostname: true,
        label: true,
        status: true,
        gamePlanId: true,
        bwInBytes: true,
        bwOutBytes: true,
        bwWindowStart: true,
        plan: { select: { bandwidthGB: true } },
        _count: { select: { portForwards: true, firewallRules: true } },
      },
    }),
    db.hostingAccount.findMany({
      where: { status: { not: "DELETING" } },
      take: HOSTING_ROWS_LIMIT,
      orderBy: { updatedAt: "desc" },
      select: {
        id: true,
        primaryDomain: true,
        status: true,
        diskUsedMB: true,
        diskQuotaMB: true,
        usageAt: true,
        serveHttpOk: true,
        serveHttpsOk: true,
      },
    }),
    readBwMeterHealth(),
  ]);

  // Latest disk sample per server, in one query (most recent SERVER_ROWS_LIMIT
  // servers only — this is a monitor view, not an export).
  const serverIds = servers.map((s) => s.id);
  const diskSamples = serverIds.length
    ? await db.serverDiskSample.findMany({
        where: { serverId: { in: serverIds } },
        orderBy: { ts: "desc" },
        // Over-fetch a bit and keep only the first (newest) row per server below —
        // Prisma has no native DISTINCT ON here without raw SQL.
        take: serverIds.length * 3,
        select: { serverId: true, ts: true, usedBytes: true, totalBytes: true },
      })
    : [];
  const latestDiskByServer = new Map<string, (typeof diskSamples)[number]>();
  for (const d of diskSamples) {
    if (!latestDiskByServer.has(d.serverId)) latestDiskByServer.set(d.serverId, d);
  }

  const actions: ActionLogLine[] = [
    ...jobs.map((j) => ({
      id: j.id,
      ts: j.createdAt.toISOString(),
      source: "JOB" as const,
      kind: serverKind({ gamePlanId: j.server?.gamePlanId ?? null }),
      target: j.server?.label || j.server?.hostname || "—",
      action: j.type.toLowerCase().replace(/_/g, " "),
      status: j.status,
      attempts: j.attempts,
      error: j.error,
    })),
    ...hostingTasks.map((t) => ({
      id: t.id,
      ts: t.createdAt.toISOString(),
      source: "HOSTING_TASK" as const,
      kind: "HOSTING" as const,
      target: t.account?.primaryDomain ?? "—",
      action: t.kind.toLowerCase().replace(/_/g, " "),
      status: t.status,
      attempts: null,
      error: t.error,
    })),
  ]
    .sort((a, b) => (a.ts < b.ts ? 1 : -1))
    .slice(0, ACTION_FEED_LIMIT);

  const serverRows: ServerRow[] = servers.map((s) => {
    const sample = latestDiskByServer.get(s.id);
    const allowanceBytes = (s.plan?.bandwidthGB ?? 0) * 1024 ** 3;
    return {
      id: s.id,
      hostname: s.hostname,
      label: s.label,
      kind: serverKind(s),
      status: s.status,
      bw: bwUsageView(
        { status: s.status, bwInBytes: s.bwInBytes, bwOutBytes: s.bwOutBytes, bwWindowStart: s.bwWindowStart },
        allowanceBytes,
        bwHealth,
        now,
      ),
      disk: sample
        ? { usedBytes: Number(sample.usedBytes), totalBytes: Number(sample.totalBytes), ts: sample.ts.toISOString() }
        : null,
      portForwards: s._count.portForwards,
      firewallRules: s._count.firewallRules,
    };
  });

  const hostingRows: HostingRow[] = hostingAccounts.map((h) => ({
    id: h.id,
    primaryDomain: h.primaryDomain,
    status: h.status,
    diskUsedMB: h.diskUsedMB,
    diskQuotaMB: h.diskQuotaMB,
    usageAt: h.usageAt ? h.usageAt.toISOString() : null,
    serveHttpOk: h.serveHttpOk,
    serveHttpsOk: h.serveHttpsOk,
  }));

  const serversByStatus: Record<string, number> = {};
  let gameServers = 0;
  let vpsServers = 0;
  for (const s of serverRows) {
    serversByStatus[s.status] = (serversByStatus[s.status] ?? 0) + 1;
    if (s.kind === "GAME") gameServers++;
    else vpsServers++;
  }
  const hostingByStatus: Record<string, number> = {};
  for (const h of hostingRows) {
    hostingByStatus[h.status] = (hostingByStatus[h.status] ?? 0) + 1;
  }

  return {
    generatedAt: now.toISOString(),
    nodes: nodeUtilResult.nodes,
    actions,
    servers: serverRows,
    hosting: hostingRows,
    totals: { serversByStatus, hostingByStatus, gameServers, vpsServers },
    bwMeter: {
      live: bwHealth.live,
      startedAt: bwHealth.startedAt ? bwHealth.startedAt.toISOString() : null,
      ageMs: bwHealth.ageMs,
    },
    gaps: [
      "No fleet-wide live per-VM CPU/RAM sample exists yet — node-level CPU/RAM above is live " +
        "(queried from Proxmox on every load of this page), but a per-server breakdown would need a new " +
        "sampling loop; polling every VM's status on every admin's poll tick was judged too much load on " +
        "Proxmox for a v1.",
      "No connection/session-count telemetry is collected anywhere on the platform. Bandwidth counters " +
        "(shown per server below) are a real traffic proxy, refreshed on the worker's ~10-minute metering " +
        "sweep, not per-request-live. Game servers CAN report live player counts over RCON, but only one " +
        "server at a time on demand — there is no sweep that samples it fleet-wide, so it is not shown here.",
    ],
  };
}

