"use client";

import { useEffect, useRef, useState } from "react";
import type { MonitorFeed, ActionLogLine, ServerRow, HostingRow } from "@/lib/monitor-feed";
import type { NodeUtil } from "@/lib/node-capacity";

const POLL_MS = 8000;

type FleetFilter = "ALL" | "VPS" | "GAME" | "HOSTING";

const STATUS_COLOR: Record<string, string> = {
  RUNNING: "text-emerald-400",
  DONE: "text-emerald-400",
  ACTIVE: "text-emerald-400",
  QUEUED: "text-amber-400",
  PENDING: "text-amber-400",
  PROVISIONING: "text-amber-400",
  REINSTALLING: "text-amber-400",
  SUSPENDED: "text-red-400",
  DELETING: "text-red-400",
  FAILED: "text-red-400",
  ERROR: "text-red-400",
  STOPPED: "text-slate-500",
};

function statusColor(status: string): string {
  return STATUS_COLOR[status] ?? "text-slate-400";
}

function hhmmss(iso: string): string {
  const d = new Date(iso);
  return d.toISOString().slice(11, 19);
}

function ageLabel(iso: string | null): string {
  if (!iso) return "never";
  const ms = Date.now() - new Date(iso).getTime();
  if (ms < 0) return "just now";
  const s = Math.floor(ms / 1000);
  if (s < 60) return `${s}s ago`;
  const m = Math.floor(s / 60);
  if (m < 60) return `${m}m ago`;
  const h = Math.floor(m / 60);
  return `${h}h ${m % 60}m ago`;
}

function fmtBytes(n: number): string {
  if (!Number.isFinite(n) || n <= 0) return "0 B";
  const units = ["B", "KB", "MB", "GB", "TB"];
  let v = n;
  let i = 0;
  while (v >= 1024 && i < units.length - 1) {
    v /= 1024;
    i++;
  }
  return `${v.toFixed(v >= 100 || i === 0 ? 0 : 1)} ${units[i]}`;
}

/** Literal ASCII meter — `[███████░░░]` — the terminal-native alternative to a <progress> bar. */
function asciiBar(pct: number, width = 16): string {
  const clamped = Math.max(0, Math.min(100, pct));
  const filled = Math.round((clamped / 100) * width);
  return "█".repeat(filled) + "░".repeat(Math.max(0, width - filled));
}

function barColor(pct: number, warn = 80, crit = 90): string {
  if (pct >= crit) return "text-red-400";
  if (pct >= warn) return "text-amber-400";
  return "text-cyan-400";
}

function kindColor(kind: string): string {
  if (kind === "GAME") return "text-brand-300";
  if (kind === "HOSTING") return "text-accent-cyan";
  return "text-accent-blue";
}

export function LiveMonitorTerminal({ initial }: { initial: MonitorFeed }) {
  const [feed, setFeed] = useState<MonitorFeed>(initial);
  const [filter, setFilter] = useState<FleetFilter>("ALL");
  const [live, setLive] = useState(true);
  const [connErr, setConnErr] = useState(false);
  const logRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!live) return;
    let cancelled = false;
    const tick = async () => {
      try {
        const res = await fetch("/api/admin/monitor-feed", { cache: "no-store" });
        if (!res.ok) throw new Error(String(res.status));
        const data: MonitorFeed = await res.json();
        if (!cancelled) {
          setFeed(data);
          setConnErr(false);
        }
      } catch {
        if (!cancelled) setConnErr(true);
      }
    };
    const t = setInterval(tick, POLL_MS);
    return () => {
      cancelled = true;
      clearInterval(t);
    };
  }, [live]);

  const actions = feed.actions.filter((a) => filter === "ALL" || a.kind === filter);
  const servers = feed.servers.filter(
    (s) => filter === "ALL" || filter === "HOSTING" ? filter !== "HOSTING" && filter !== "ALL" ? s.kind === filter : filter === "ALL" : s.kind === filter,
  );
  const hosting = feed.hosting; // shown only in ALL/HOSTING filter below

  return (
    <div className="rounded-xl border border-cyan-500/20 bg-black/80 font-mono text-[13px] shadow-[0_0_60px_-15px_rgba(34,211,238,0.25)]">
      {/* Window chrome */}
      <div className="flex items-center justify-between border-b border-white/10 px-4 py-2.5">
        <div className="flex items-center gap-2">
          <span className="h-2.5 w-2.5 rounded-full bg-red-500/70" />
          <span className="h-2.5 w-2.5 rounded-full bg-amber-500/70" />
          <span className="h-2.5 w-2.5 rounded-full bg-emerald-500/70" />
          <span className="ml-3 text-slate-400">root@nxeon</span>
          <span className="text-slate-600">:</span>
          <span className="text-cyan-400">~/fleet/live-ops</span>
        </div>
        <div className="flex items-center gap-4 text-xs">
          {connErr && <span className="text-red-400">poll failed — retrying</span>}
          <span className="flex items-center gap-1.5 text-slate-500">
            <span
              className={`h-1.5 w-1.5 rounded-full ${live ? "animate-pulse bg-emerald-400" : "bg-slate-600"}`}
            />
            {live ? `polling ${POLL_MS / 1000}s` : "paused"}
          </span>
          <button
            type="button"
            onClick={() => setLive((v) => !v)}
            className="rounded border border-white/10 px-2 py-0.5 text-slate-400 hover:border-cyan-500/40 hover:text-cyan-300"
          >
            {live ? "pause" : "resume"}
          </button>
          <span className="text-slate-600">gen {hhmmss(feed.generatedAt)}Z</span>
        </div>
      </div>

      {/* Summary line */}
      <div className="flex flex-wrap items-center gap-x-6 gap-y-1 border-b border-white/10 bg-white/[0.02] px-4 py-2 text-xs text-slate-400">
        <span>
          vps <span className="text-slate-200">{feed.totals.vpsServers}</span>
        </span>
        <span>
          game <span className="text-slate-200">{feed.totals.gameServers}</span>
        </span>
        <span>
          hosting <span className="text-slate-200">{feed.hosting.length}</span>
        </span>
        {Object.entries(feed.totals.serversByStatus).map(([st, n]) => (
          <span key={st}>
            <span className={statusColor(st)}>{st.toLowerCase()}</span>{" "}
            <span className="text-slate-200">{n}</span>
          </span>
        ))}
        <span className="ml-auto flex gap-1">
          {(["ALL", "VPS", "GAME", "HOSTING"] as FleetFilter[]).map((f) => (
            <button
              key={f}
              type="button"
              onClick={() => setFilter(f)}
              className={`rounded border px-2 py-0.5 ${
                filter === f
                  ? "border-cyan-500/50 bg-cyan-500/10 text-cyan-300"
                  : "border-white/10 text-slate-500 hover:text-slate-300"
              }`}
            >
              {f.toLowerCase()}
            </button>
          ))}
        </span>
      </div>

      <div className="grid grid-cols-1 gap-px bg-white/5 lg:grid-cols-[minmax(0,1fr)_360px]">
        {/* Action log */}
        <div className="bg-black/60 p-3">
          <div className="mb-2 text-[11px] uppercase tracking-widest text-slate-600">
            recent actions — tail -f (Job + HostingTask, {actions.length} shown)
          </div>
          <div ref={logRef} className="max-h-[520px] overflow-y-auto pr-1">
            {actions.length === 0 && <div className="text-slate-600">-- no recent activity --</div>}
            {actions.map((a) => (
              <ActionLine key={a.id} a={a} />
            ))}
          </div>
        </div>

        {/* Node gauges */}
        <div className="bg-black/60 p-3">
          <div className="mb-2 text-[11px] uppercase tracking-widest text-slate-600">
            node load — live from proxmox
          </div>
          <div className="space-y-3">
            {feed.nodes.length === 0 && <div className="text-slate-600">-- no nodes reachable --</div>}
            {feed.nodes.map((n) => (
              <NodeGauge key={`${n.kind}:${n.id}`} n={n} />
            ))}
          </div>
        </div>
      </div>

      {/* Server / hosting table */}
      <div className="border-t border-white/10 bg-black/60 p-3">
        <div className="mb-2 text-[11px] uppercase tracking-widest text-slate-600">
          fleet resource state — bandwidth + disk sampled by worker (~10min cadence), refreshed{" "}
          {ageLabel(feed.bwMeter.startedAt)} since first metered
        </div>
        <div className="overflow-x-auto">
          <table className="w-full min-w-[720px] border-collapse text-xs">
            <thead>
              <tr className="border-b border-white/10 text-left text-slate-600">
                <th className="py-1 pr-3">kind</th>
                <th className="py-1 pr-3">target</th>
                <th className="py-1 pr-3">status</th>
                <th className="py-1 pr-3">bandwidth</th>
                <th className="py-1 pr-3">disk</th>
                <th className="py-1 pr-3">net rules</th>
              </tr>
            </thead>
            <tbody>
              {(filter === "HOSTING" ? [] : servers).map((s) => (
                <ServerLine key={s.id} s={s} />
              ))}
              {(filter === "ALL" || filter === "HOSTING") &&
                hosting.map((h) => <HostingLine key={h.id} h={h} />)}
            </tbody>
          </table>
        </div>
      </div>

      {/* Honest gaps */}
      <div className="border-t border-white/10 px-4 py-2.5 text-[11px] leading-relaxed text-slate-600">
        {feed.gaps.map((g, i) => (
          <div key={i}>
            <span className="text-slate-700"># </span>
            {g}
          </div>
        ))}
      </div>
    </div>
  );
}

function ActionLine({ a }: { a: ActionLogLine }) {
  return (
    <div className="flex flex-wrap items-baseline gap-x-2 whitespace-nowrap py-0.5 leading-relaxed hover:bg-white/[0.03]">
      <span className="text-slate-600">{hhmmss(a.ts)}</span>
      <span className={`w-16 shrink-0 ${kindColor(a.kind)}`}>[{a.kind}]</span>
      <span className="min-w-[10ch] truncate text-slate-300">{a.target}</span>
      <span className="text-slate-400">{a.action}</span>
      <span className={`${statusColor(a.status)} font-semibold`}>{a.status.toLowerCase()}</span>
      {a.attempts !== null && a.attempts > 1 && (
        <span className="text-amber-500/80">×{a.attempts}</span>
      )}
      {a.error && (
        <span className="max-w-[40ch] truncate text-red-400/80" title={a.error}>
          — {a.error}
        </span>
      )}
    </div>
  );
}

function NodeGauge({ n }: { n: NodeUtil }) {
  return (
    <div className="rounded border border-white/10 p-2">
      <div className="mb-1 flex items-center justify-between">
        <span className="text-slate-300">{n.name}</span>
        <span className="text-[10px] text-slate-600">{n.kind === "PROXMOX" ? "compute" : "hosting"}</span>
      </div>
      {!n.reachable && n.kind === "PROXMOX" ? (
        <div className="text-red-400/80">unreachable</div>
      ) : n.dims.length === 0 ? (
        <div className="text-slate-600">no dimensions reported</div>
      ) : (
        n.dims.map((d) => (
          <div key={d.dimension} className="flex items-baseline gap-2">
            <span className="w-14 shrink-0 text-slate-500">{d.dimension.toLowerCase()}</span>
            <span className={barColor(d.pct)}>{asciiBar(d.pct)}</span>
            <span className={`w-10 shrink-0 text-right ${barColor(d.pct)}`}>{Math.round(d.pct)}%</span>
          </div>
        ))
      )}
    </div>
  );
}

function ServerLine({ s }: { s: ServerRow }) {
  const bwPct = s.bw.measured && s.bw.pct !== null ? s.bw.pct : null;
  const diskPct = s.disk && s.disk.totalBytes > 0 ? (s.disk.usedBytes / s.disk.totalBytes) * 100 : null;
  return (
    <tr className="border-b border-white/5 hover:bg-white/[0.03]">
      <td className={`py-1 pr-3 ${kindColor(s.kind)}`}>{s.kind.toLowerCase()}</td>
      <td className="py-1 pr-3 text-slate-300">{s.label || s.hostname}</td>
      <td className={`py-1 pr-3 ${statusColor(s.status)}`}>{s.status.toLowerCase()}</td>
      <td className="py-1 pr-3 text-slate-400">
        {bwPct === null ? (
          <span className="text-slate-700">not metered</span>
        ) : (
          <>
            {fmtBytes(s.bw.usedBytes)} <span className={barColor(bwPct)}>({Math.round(bwPct)}%)</span>
          </>
        )}
      </td>
      <td className="py-1 pr-3 text-slate-400">
        {diskPct === null ? (
          <span className="text-slate-700">—</span>
        ) : (
          <>
            {fmtBytes(s.disk!.usedBytes)}{" "}
            <span className={barColor(diskPct)}>({Math.round(diskPct)}%)</span>{" "}
            <span className="text-slate-700">{ageLabel(s.disk!.ts)}</span>
          </>
        )}
      </td>
      <td className="py-1 pr-3 text-slate-500">
        {s.portForwards} fwd · {s.firewallRules} fw
      </td>
    </tr>
  );
}

function HostingLine({ h }: { h: HostingRow }) {
  const diskPct = h.diskUsedMB !== null && h.diskQuotaMB > 0 ? (h.diskUsedMB / h.diskQuotaMB) * 100 : null;
  const health =
    h.serveHttpOk === null
      ? { label: "unchecked", cls: "text-slate-700" }
      : h.serveHttpOk && h.serveHttpsOk
        ? { label: "serving", cls: "text-emerald-400" }
        : { label: "not serving", cls: "text-red-400" };
  return (
    <tr className="border-b border-white/5 hover:bg-white/[0.03]">
      <td className="py-1 pr-3 text-accent-cyan">hosting</td>
      <td className="py-1 pr-3 text-slate-300">{h.primaryDomain}</td>
      <td className={`py-1 pr-3 ${statusColor(h.status)}`}>{h.status.toLowerCase()}</td>
      <td className="py-1 pr-3 text-slate-400">
        <span className={health.cls}>{health.label}</span>
      </td>
      <td className="py-1 pr-3 text-slate-400">
        {diskPct === null ? (
          <span className="text-slate-700">not measured</span>
        ) : (
          <>
            {h.diskUsedMB} / {h.diskQuotaMB} MB{" "}
            <span className={barColor(diskPct)}>({Math.round(diskPct)}%)</span>{" "}
            <span className="text-slate-700">{ageLabel(h.usageAt)}</span>
          </>
        )}
      </td>
      <td className="py-1 pr-3 text-slate-700">—</td>
    </tr>
  );
}

